python3 - <<'EOF'
import re,os
lines=open('README.md').read().split('\n')
block=lines[261:291]
refs=[];paths=[]
for l in block:
    m=re.search(r'@ref:([\w\-/]+)',l)
    if m: refs.append(m.group(1))
    m2=re.search(r'→\s*(\S+)',l)
    if m2: paths.append(m2.group(1))
for r,p in zip(refs,paths):
    print(f"{r:45s} {p:55s} exists={os.path.exists(p)}")
EOF
